using Xunit;
using Moq;
using Microsoft.Extensions.Logging;
using System;
using Garnet.server.TLS;

public class ServerCertificateSelectorTests
{
    [Fact]
    public void LogError_WhenCertificateFetchFails_LogsCorrectMessage()
    {
        // Arrange
        var loggerMock = new Mock<ILogger>();
        var certificateSelector = new Mock<ServerCertificateSelector>("invalidFile", "invalidPassword", 0, loggerMock.Object);

        certificateSelector.Setup(cs => cs.GetCertificate()).Throws(new Exception("Simulated exception"));

        // Act
        certificateSelector.Object.GetSslServerCertificate();

        // Assert
        loggerMock.Verify(
            logger => logger.LogError(
                It.Is<string>(s => s.Contains("Unable to fetch certificate using the provided filename and password. Make sure you specify a correct CertFileName and CertPassword.")),
                It.IsAny<object[]>()),
            Times.Once);
    }
}
